/**
 * U4.1 — On-chain pubSignals Binding Test (Groth16Verifier ↔ metering_v1 proof)
 *
 * Validates that MeteringVerifier.sol (Groth16Verifier generated by snarkjs) correctly:
 *   1. Returns true  for verifyProof(a,b,c, [commitment, epoch, maxUsage])  ← CORRECT order
 *   2. Returns false for verifyProof(a,b,c, [epoch, maxUsage, commitment])  ← OLD wrong order
 *   3. Returns false for verifyProof(a,b,c, [commitment, epoch, maxUsage+1]) ← tampered input
 *
 * Also validates ReceiptRegistry end-to-end happy path with real Groth16Verifier.
 *
 * Inputs: zk/build/proof.json + zk/build/public.json (generated by snarkjs groth16 prove)
 * Network: Hardhat in-process (ephemeral, no Besu required)
 */

import { describe, it, before } from "node:test";
import assert from "node:assert/strict";
import hre from "hardhat";
import { ethers } from "ethers";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..", "..", "..");
const BUILD = path.join(ROOT, "zk", "build");

function readJson(p) { return JSON.parse(fs.readFileSync(p, "utf8")); }

/** Convert snarkjs proof.json + public.json to Solidity verifyProof args */
function proofToSolidity(proof, pub) {
  const a  = [proof.pi_a[0], proof.pi_a[1]];
  // Groth16: pi_b points are in reversed coordinate order for Solidity
  const b  = [
    [proof.pi_b[0][1], proof.pi_b[0][0]],
    [proof.pi_b[1][1], proof.pi_b[1][0]],
  ];
  const c  = [proof.pi_c[0], proof.pi_c[1]];
  return { a, b, c, input: pub }; // pub = [commitment, epoch, maxUsage]
}

/** Create a deterministic test wallet from seed */
function createWallet(seed) {
  const hash = ethers.keccak256(ethers.toUtf8Bytes(seed));
  return new ethers.Wallet(hash);
}

describe("U4.1 — On-chain pubSignals Binding (Groth16Verifier ↔ metering_v1)", () => {
  let conn;
  let deployer;
  let proof;
  let pub;
  let solProof;

  before(async () => {
    conn = await hre.network.connect();
    const signers = await conn.ethers.getSigners();
    deployer = signers[0];

    // Load ZK artifacts
    assert.ok(fs.existsSync(path.join(BUILD, "proof.json")),  "zk/build/proof.json must exist");
    assert.ok(fs.existsSync(path.join(BUILD, "public.json")), "zk/build/public.json must exist");
    proof = readJson(path.join(BUILD, "proof.json"));
    pub   = readJson(path.join(BUILD, "public.json"));

    assert.equal(pub.length, 3, "public.json must have 3 signals: [commitment, epoch, maxUsage]");
    solProof = proofToSolidity(proof, pub);
  });

  // ─── Test A: pubSignals structure ────────────────────────────

  it("A) public.json has canonical order [commitment, epoch, maxUsage]", () => {
    const commitment = BigInt(pub[0]);
    const epoch      = BigInt(pub[1]);
    const maxUsage   = BigInt(pub[2]);

    // commitment is a large Poseidon field element — much larger than epoch or maxUsage
    assert.ok(commitment > maxUsage,   "commitment > maxUsage (structural sanity)");
    assert.ok(commitment > epoch,      "commitment > epoch (structural sanity)");
    // epoch is a small integer (floor(timestamp/3600) or 1 for test)
    assert.ok(epoch < 1_000_000_000n, "epoch is a reasonable timestamp value");
    // maxUsage is bounded
    assert.ok(maxUsage >= epoch,       "maxUsage >= epoch");
  });

  // ─── Test B: Groth16Verifier happy path ──────────────────────

  it("B) verifyProof([commitment, epoch, maxUsage]) = true (correct canonical order)", async () => {
    const VerifierFactory = await conn.ethers.getContractFactory("contracts/MeteringVerifier.sol:Groth16Verifier");
    const verifier = await VerifierFactory.deploy();
    await verifier.waitForDeployment();

    const ok = await verifier.verifyProof(
      solProof.a,
      solProof.b,
      solProof.c,
      solProof.input  // [commitment, epoch, maxUsage]
    );
    assert.equal(ok, true, "verifyProof must return true for canonical pubSignals order");
  });

  // ─── Test C: Wrong order → proof invalid ─────────────────────

  it("C) verifyProof([epoch, maxUsage, commitment]) = false (old wrong order)", async () => {
    const VerifierFactory = await conn.ethers.getContractFactory("contracts/MeteringVerifier.sol:Groth16Verifier");
    const verifier = await VerifierFactory.deploy();
    await verifier.waitForDeployment();

    const wrongOrder = [pub[1], pub[2], pub[0]]; // [epoch, maxUsage, commitment] — OLD wrong order

    const ok = await verifier.verifyProof(
      solProof.a,
      solProof.b,
      solProof.c,
      wrongOrder
    );
    assert.equal(ok, false, "verifyProof must return false for wrong pubSignals order");
  });

  // ─── Test D: Tampered input → proof invalid ──────────────────

  it("D) verifyProof with tampered input = false", async () => {
    const VerifierFactory = await conn.ethers.getContractFactory("contracts/MeteringVerifier.sol:Groth16Verifier");
    const verifier = await VerifierFactory.deploy();
    await verifier.waitForDeployment();

    const tampered = [pub[0], (BigInt(pub[1]) + 1n).toString(), pub[2]]; // epoch+1

    const ok = await verifier.verifyProof(solProof.a, solProof.b, solProof.c, tampered);
    assert.equal(ok, false, "verifyProof must return false for tampered pubSignals");
  });

  // ─── Test E: ReceiptRegistry end-to-end with real verifier ───

  it("E) ReceiptRegistry + Groth16Verifier: submitReceipt happy path", async () => {
    const signers = await conn.ethers.getSigners();
    const submitter = signers[1];

    // Deploy real Groth16Verifier
    const VerifierFactory = await conn.ethers.getContractFactory("contracts/MeteringVerifier.sol:Groth16Verifier");
    const verifier = await VerifierFactory.deploy();
    await verifier.waitForDeployment();

    // Trusted signer (off-chain wallet)
    const trustedWallet = createWallet("u4-1-trusted-signer");

    // Deploy ReceiptRegistry with real verifier
    const RegFactory = await conn.ethers.getContractFactory("ReceiptRegistry");
    const registry = await RegFactory.deploy(
      await verifier.getAddress(),
      trustedWallet.address
    );
    await registry.waitForDeployment();

    // Build RawReceiptData matching metering_input.json
    // epoch=1, userId=12345678901234567890 — but userId may overflow uint256 range test
    // Use a safe userId for on-chain test
    const safeUserId = 12345n;
    const raw = {
      userId:    safeUserId,
      nonce:     0n,
      epoch:     BigInt(pub[1]),   // epoch from proof (pubSignals[1])
      costUnits: 999n,
    };

    // Sign rawHash with trustedWallet (EIP-191 personal sign)
    const rawHashStr  = ethers.keccak256(ethers.toUtf8Bytes("u4-1-real-proof-receipt"));
    const rawHashBytes = ethers.getBytes(rawHashStr);
    const sig = ethers.Signature.from(await trustedWallet.signMessage(rawHashBytes));

    // ProofData: pubSignals in canonical order [commitment, epoch, maxUsage]
    const proofData = {
      a: solProof.a,
      b: solProof.b,
      c: solProof.c,
      pubSignals: solProof.input,  // [commitment, epoch, maxUsage]
    };

    const registryAsSubmitter = registry.connect(submitter);
    const tx = await registryAsSubmitter.submitReceipt(
      raw, rawHashStr, sig.v, sig.r, sig.s, proofData
    );
    const receipt = await tx.wait();

    // Verify ReceiptSubmitted event emitted
    const event = receipt.logs
      .map(log => { try { return registry.interface.parseLog(log); } catch { return null; } })
      .find(e => e?.name === "ReceiptSubmitted");

    assert.ok(event, "ReceiptSubmitted event must be emitted");
    assert.equal(event.args.userId,    safeUserId,       "userId must match");
    assert.equal(event.args.costUnits, raw.costUnits,    "costUnits must match");
    assert.equal(event.args.epoch,     raw.epoch,        "epoch must match pubSignals[1]");
  });
});
